                results += response.json()

        return results"", ""found"": true, ""signature"": """", ""callsite_slice"": """", ""evidence_slice"": """", ""match_score"": 0, ""confidence"": 0.0, ""confidence_label"": """"}]",,[],[],True,skipped_fixer_only,"def get_groups(self):

