  const DeviceGuard device_guard(device_or_default(device));""""""

                        # CUDA requires special handling
                        if is_cuda_dispatch_key(self.backend_index.dispatch_key):
                            device_guard = (
                                f""globalContext().lazyInitCUDA();\n{device_guard}""
                            )
                    else:
